@st.cache_data
def load_data():
    df = pd.read_csv(DATA_PATH)
    numeric = ["Academic_Percentage_Clean","Study_Hours_Clean","Study_Days_Clean","Attendance_Clean",
               "Sleep_Hours_Clean","NonAcademic_Screen_Clean","Academic_Screen_Clean","Group_Study_Hours_Clean"]
    for c in numeric:
        if c in df: df[c] = pd.to_numeric(df[c], errors="coerce")
    return df

df = load_data()

def chart_theme(fig, height=390):
    dark = st.session_state.get("dashboard_dark_mode", False)
    ink = "#F3EBDD" if dark else "#30251F"
    surface = "#222633" if dark else "#FFFCF6"
    grid = "#41485A" if dark else "#E6DCCB"
    maroon = "#E6A0AE" if dark else "#741B32"
    gold = "#9C8353" if dark else "#D9C5A3"
    fig.update_layout(
        height=height, autosize=True, paper_bgcolor=surface, plot_bgcolor=surface,
        font=dict(family="Times New Roman", color=ink, size=16),
        margin=dict(l=82, r=32, t=55, b=100),
        legend=dict(orientation="h", y=-0.25, font=dict(family="Times New Roman", size=14, color=ink)),
        title_font=dict(family="Playfair Display", size=18, color=maroon),
    )
    fig.update_xaxes(showgrid=False, linecolor=gold,
        tickfont=dict(family="Times New Roman", size=14, color=ink),
        title_font=dict(family="Times New Roman", size=15, color=ink), automargin=True)
    fig.update_yaxes(gridcolor=grid, zeroline=False,
        tickfont=dict(family="Times New Roman", size=14, color=ink),
        title_font=dict(family="Times New Roman", size=15, color=ink), automargin=True)
    return fig

def panel_title(title, icon="✿"):
    st.markdown(f'<div class="section-head">{icon} &nbsp;{title}</div>', unsafe_allow_html=True)

def panel_end():
    pass

def metric(label, value, icon):
    st.markdown(f'<div class="metric"><div style="font-size:25px">{icon}</div><div class="value">{value}</div><div class="label">{label}</div></div>',unsafe_allow_html=True)

def explanation(text):
    st.markdown(f'<div class="explain">{text}</div>', unsafe_allow_html=True)

def safe_mean(col):
    return df[col].mean() if col in df else np.nan

def show_bar(data, col, title, horizontal=False, height=390):
    if col not in data:
        st.info(f"{col} is not available in this dataset.")
        return
    counts=data[col].fillna("Not reported").astype(str).value_counts().rename_axis("Category").reset_index(name="Students")
    if horizontal:
        fig=px.bar(counts.sort_values("Students"),x="Students",y="Category",orientation="h",
                   text="Students",color="Category",color_discrete_sequence=PALETTE)
        fig.update_layout(yaxis=dict(categoryorder="total ascending"))
    else:
        fig=px.bar(counts,x="Category",y="Students",text="Students",color="Category",
                   color_discrete_sequence=PALETTE)
    fig.update_traces(textposition="outside", textfont=dict(size=13,color="#32103E"),
                      marker_line_color="#FFFFFF",marker_line_width=1)
    fig.update_layout(showlegend=False, title=title)
    st.plotly_chart(chart_theme(fig,height),use_container_width=True, config={"displayModeBar":True,"responsive":True,"displaylogo":False,"modeBarButtonsToAdd":["zoom2d","pan2d","resetScale2d","toImage"]})

def countplot(data, col, title, horizontal=False, height=390):
    show_bar(data,col,title,horizontal,height)

def piechart(data,col,title):
    if col not in data: return
    counts=data[col].fillna("Not reported").astype(str).value_counts().rename_axis("Category").reset_index(name="Students")
    fig=px.pie(counts,names="Category",values="Students",hole=.30,color_discrete_sequence=PALETTE)
    fig.update_traces(textposition="inside",textinfo="percent+label",insidetextfont=dict(size=13,color="#32103E"),
                      marker=dict(line=dict(color="#FFFFFF",width=2)))
    fig.update_layout(title=title)
    st.plotly_chart(chart_theme(fig,370),use_container_width=True, config={"displayModeBar":True,"responsive":True,"displaylogo":False,"modeBarButtonsToAdd":["zoom2d","pan2d","resetScale2d","toImage"]})

