# Global filters. Each dropdown starts at "All" and changes the dataset used by every page.
filter_low = float(np.floor(df["Academic_Percentage_Clean"].min()))
filter_high = float(np.ceil(df["Academic_Percentage_Clean"].max()))

def reset_filter_state():
    st.session_state["year_filter_final"] = "All Years"
    st.session_state["gender_filter_final"] = "All Genders"
    st.session_state["score_filter_final"] = (filter_low, filter_high)

with st.expander("🔎  Explore the data with filters", expanded=False):
    f1, f2, f3, f4 = st.columns([1, 1, 1.35, 0.65], gap="medium")
    years = ["All Years"] + sorted(df["Year_Clean"].dropna().astype(str).unique().tolist())
    genders = ["All Genders"] + sorted(df["Gender"].dropna().astype(str).unique().tolist())
    year_choice = f1.selectbox("Year of study", years, index=0, key="year_filter_final")
    gender_choice = f2.selectbox("Gender", genders, index=0, key="gender_filter_final")
    score_range = f3.slider("Academic percentage range", min_value=filter_low, max_value=filter_high,
                            value=(filter_low, filter_high), step=1.0, key="score_filter_final")
    f4.button("Reset filters", use_container_width=True, on_click=reset_filter_state)

filtered = df.copy()
if year_choice != "All Years":
    filtered = filtered[filtered["Year_Clean"].astype(str) == year_choice]
if gender_choice != "All Genders":
    filtered = filtered[filtered["Gender"].astype(str) == gender_choice]
score_mask = filtered["Academic_Percentage_Clean"].between(*score_range) | filtered["Academic_Percentage_Clean"].isna()
filtered = filtered[score_mask]
st.caption(f"Showing **{len(filtered):,} of {len(df):,} participants** based on the current filters. Participants without a recorded academic percentage remain included in the participant count.")

def countplot(data, col, title, horizontal=False, height=390):
    if col not in data:
        st.info(f"{col} is not available in this dataset.")
        return
    counts=data[col].fillna("Not reported").astype(str).value_counts().rename_axis("Category").reset_index(name="Students")
    if horizontal:
        counts=counts.sort_values("Students",ascending=True)
        dynamic_height=max(height, min(620, 105 + len(counts)*43))
        fig=px.bar(counts,x="Students",y="Category",orientation="h",text="Students",
                   color="Category",color_discrete_sequence=PALETTE)
        fig.update_yaxes(categoryorder="array",categoryarray=counts["Category"].tolist(),automargin=True)
        left_margin=190
        chart_height=dynamic_height
    else:
        fig=px.bar(counts,x="Category",y="Students",text="Students",
                   color="Category",color_discrete_sequence=PALETTE)
        left_margin=55
        chart_height=height
    label_ink = "#F3EBDD" if st.session_state.get("dashboard_dark_mode", False) else "#30251F"
    fig.update_traces(textposition="outside",textfont=dict(family="Times New Roman",size=15,color=label_ink),
                      marker_line_color="#fffaf2",marker_line_width=1.5,cliponaxis=False)
    fig.update_layout(showlegend=False,title=title,
                      margin=dict(l=left_margin,r=35,t=48,b=90),
                      height=chart_height)
    fig = chart_theme(fig, chart_height)
    fig.update_layout(margin=dict(l=left_margin, r=35, t=55, b=100))
    st.plotly_chart(fig,use_container_width=True,config={"displayModeBar":True,"responsive":True,"displaylogo":False,"modeBarButtonsToAdd":["zoom2d","pan2d","resetScale2d","toImage"]})

def piechart(data,col,title):
    if col not in data:
        st.info(f"{col} is not available in this dataset.")
        return
    counts=data[col].fillna("Not reported").astype(str).value_counts().rename_axis("Category").reset_index(name="Students")
    fig=px.pie(counts,names="Category",values="Students",hole=.38,color_discrete_sequence=PALETTE)
    dark = st.session_state.get("dashboard_dark_mode", False)
    ink = "#F3EBDD" if dark else "#30251F"
    surface = "#222633" if dark else "#FFFCF6"
    fig.update_traces(textposition="inside",textinfo="percent",
                      insidetextfont=dict(family="Times New Roman",size=14,color=ink),
                      marker=dict(line=dict(color=surface,width=2)))
    fig.update_layout(title=title,showlegend=True,
                      margin=dict(l=8,r=8,t=45,b=95),
                      legend=dict(orientation="h",y=-.22,x=.5,xanchor="center",
                                  font=dict(family="Times New Roman",size=14,color=ink)))
    st.plotly_chart(chart_theme(fig,350),use_container_width=True,
                    config={"displayModeBar":True,"responsive":True,"displaylogo":False,
                            "modeBarButtonsToAdd":["zoom2d","pan2d","resetScale2d","toImage"]})

