        explanation("Interpretation: The histogram identifies score ranges where participants are concentrated. The rating chart compares the recorded performance categories. Neither chart by itself explains the causes of academic performance.")
        panel_end()

        # 3. Study habits and learning patterns
        panel_title("Study Habits and Learning Patterns", "📚")
        st.caption("Daily study time and the methods students report using most often.")
        h1, h2 = st.columns(2, gap="large")
