        available=[c for c in corr_cols if c in filtered and filtered[c].notna().sum()>2]
        if len(available)>1:
            cm=filtered[available].corr(method="spearman")
            fig=px.imshow(cm,zmin=-1,zmax=1,color_continuous_scale="RdPu",text_auto=".2f",aspect="auto")
            st.plotly_chart(chart_theme(fig,650),use_container_width=True,config={"displayModeBar":True,"responsive":True,"displaylogo":False,"modeBarButtonsToAdd":["zoom2d","pan2d","resetScale2d","toImage"]})
            explanation("Interpretation: This Spearman correlation heatmap summarises the direction and strength of relationships between the numerical variables. Values range from -1 to +1. Values closer to +1 indicate a stronger positive association, values closer to -1 indicate a stronger negative association, and values near 0 indicate little or no monotonic association. The diagonal is 1.00 because each variable is perfectly correlated with itself. Correlation does not establish cause and effect.")
            target="Academic_Percentage_Clean"
            if target in available:
                rows=[]
                for col in available:
                    if col==target: continue
                    v=filtered[[col,target]].dropna()
                    if len(v)>2:
                        rho,p=spearmanr(v[col],v[target])
                        rows.append({"Variable":col,"Spearman rho":rho,"p-value":p,"Valid responses":len(v)})
                st.dataframe(pd.DataFrame(rows).round(4),use_container_width=True)
                explanation("How to read the table: Spearman rho indicates the direction and strength of each relationship with academic percentage. A positive value means the two variables tend to increase together; a negative value means one tends to decrease as the other increases. The p-value helps assess statistical evidence, while the valid-response count shows how many paired records were used. Interpret both the size of rho and the p-value; neither demonstrates causation.")
        else: st.info("Not enough numeric data for correlation analysis under these filters.")
